class Fraction:
    def __init__(self, numerator, denominator):
        if denominator == 0:
            raise ValueError("Denominator cannot be zero")
        self.numerator = numerator
        self.denominator = denominator

    def add(self, other):
        new_numerator = self.numerator * other.denominator + self.denominator * other.numerator
        new_denominator = self.denominator * other.denominator
        return Fraction(new_numerator, new_denominator)

    def subtract(self, other):
        new_numerator = self.numerator * other.denominator - self.denominator * other.numerator
        new_denominator = self.denominator * other.denominator
        return Fraction(new_numerator, new_denominator)

    def multiply(self, other):
        new_numerator = self.numerator * other.numerator
        new_denominator = self.denominator * other.denominator
        return Fraction(new_numerator, new_denominator)

    def divide(self, other):
        new_numerator = self.numerator * other.denominator
        new_denominator = self.denominator * other.numerator
        return Fraction(new_numerator, new_denominator)


# Example usage
f1 = Fraction(1, 2)
f2 = Fraction(1, 4)

print(f1.add(f2))  # Output: 3/4
print(f1.subtract(f2))  # Output: 1/4
print(f1.multiply(f2))  # Output: 1/8
print(f1.divide(f2))  # Output: 2/4 (simplified to 1)
```

This program defines a `Fraction` class with methods for addition, subtraction, multiplication, and division. The `add`, `subtract`, `multiply`, and `divide` methods take another `Fraction` object as an argument and return a new `Fraction` object with the result of the operation. The `__init__` method ensures that the denominator cannot be zero, and the `simplify` method is used to simplify the fraction after the operation.
